    public List<ClinicalEntry> search(String query) {
        if (query == null || query.isBlank()) {
            return Collections.unmodifiableList(REGISTRY);
        }
        String q = query.toLowerCase().trim();
        return REGISTRY.stream()
                .filter(e -> e.getCode().toLowerCase().contains(q) ||
                             e.getName().toLowerCase().contains(q) ||
                             e.getCategory().toLowerCase().contains(q) ||
                             e.getPathophysiology().toLowerCase().contains(q))
                .collect(Collectors.toList());
    }

    public Optional<ClinicalEntry> findByCode(String code) {
        return REGISTRY.stream()
                .filter(e -> e.getCode().equalsIgnoreCase(code))
                .findFirst();
    }

    public int getTotalEntriesCount() {
        return REGISTRY.size();
    }
